<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { formatTime, platformApi, statusText } from '../api'
import ModalDialog from '../components/ModalDialog.vue'
import PageState from '../components/PageState.vue'
import FilterSelect from '../components/FilterSelect.vue'
const tab=ref('tenants');const loading=ref(false);const saving=ref(false);const error=ref('');const notice=ref('');const modal=ref(false);const metrics=ref<Record<string,number>>({});const tenants=ref<any[]>([]);const tenantsQuery=ref('');const settings=ref<any[]>([]);const audits=ref<any[]>([]);const roleTemplates=ref<any[]>([]);const selectedRoleTemplates=reactive<Record<string,boolean>>({})
/* ===== 平台辅助人员（仅平台管理员可见；辅助人员按分配权限访问，不能再管理平台人员） ===== */
const role=ref<string>(localStorage.getItem('clothp_platform_role')||'super')
const assistants=ref<any[]>([]);const assistantCatalog=ref<any[]>([]);const assistantModal=ref(false)
const assistantForm=reactive({login_name:'',name:'',password:'',permissions:{} as Record<string,boolean>})
const permEditItem=ref<any>(null);const permEdit=reactive({codes:{} as Record<string,boolean>})
const registrations=ref<any[]>([]);const regStatus=ref('pending')
const approveModal=ref(false);const approveItem=ref<any>(null)
const approveForm=reactive({edition:'basic',user_limit:20,short_code:'',admin_login_name:'',admin_name:'系统管理员',admin_password:'123456123456',reason:''})
const form=reactive({code:'',name:'',short_code:'',timezone:'Asia/Shanghai',admin_login_name:'',admin_name:'系统管理员',admin_password:'123456123456',role_template_mode:'all'});
let previewTimer:any=undefined
function openRegister(){Object.assign(form,{code:'',name:'',short_code:'',timezone:'Asia/Shanghai',admin_login_name:'',admin_name:'系统管理员',admin_password:'123456123456',role_template_mode:'all'});Object.keys(selectedRoleTemplates).forEach(k=>delete selectedRoleTemplates[k]);error.value='';modal.value=true}
async function previewTenant(){const name=form.name.trim();if(!name)return;try{const r=await platformApi<{code:string;short_code:string;admin_login_name:string;admin_password:string}>('/tenants/preview?name='+encodeURIComponent(name)+'&code='+encodeURIComponent(form.code.trim()));form.code=r.code;form.short_code=r.short_code;form.admin_login_name=r.admin_login_name;if(!form.admin_password)form.admin_password=r.admin_password}catch{}}
function onTenantNameInput(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>previewTenant(),350)}
function onShortCodeInput(){if(form.short_code)form.admin_login_name=form.short_code.toUpperCase()+'admin'}const setting=reactive({setting_key:'',value:'',reason:''})
const adminModal=ref(false);const adminTenant=ref<any>(null);const adminUsers=ref<any[]>([]);const temporaryPassword=ref('')
const cards=[['tenant_count','租户总数'],['active_tenant_count','启用租户'],['disabled_tenant_count','停用租户'],['user_count','用户总数'],['work_order_count','工单总数'],['report_count','报工总数']]
async function load(){loading.value=true;error.value='';try{/* 辅助人员可能没有全部权限：单个请求失败不影响其余页签 */const rs=await Promise.allSettled([platformApi<{metrics:Record<string,number>}>('/statistics'),platformApi<{items:any[]}>(tenantsQuery.value.trim()?'/tenants?q='+encodeURIComponent(tenantsQuery.value.trim()):'/tenants'),platformApi<{items:any[]}>('/settings'),platformApi<{items:any[]}>('/audit-logs'),platformApi<{items:any[]}>('/role-templates'),platformApi<{items:any[]}>('/tenant-registrations?status='+regStatus.value)]);const ok=(i:number,d:any)=>rs[i].status==='fulfilled'?rs[i].value:d;metrics.value=ok(0,{metrics:{}}).metrics||{};tenants.value=ok(1,{items:[]}).items;settings.value=ok(2,{items:[]}).items;audits.value=ok(3,{items:[]}).items;roleTemplates.value=ok(4,{items:[]}).items;registrations.value=ok(5,{items:[]}).items;const failures=rs.filter(r=>r.status==='rejected');if(failures.length===rs.length)error.value=(failures[0] as PromiseRejectedResult).reason?.message||'加载失败';else if(failures.length)notice.value=`部分板块无权查看（${failures.length} 项），已按辅助人员权限隐藏`}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function register(){saving.value=true;error.value='';try{const role_template_ids=form.role_template_mode==='custom'?Object.keys(selectedRoleTemplates).filter(id=>selectedRoleTemplates[id]):undefined;const result=await platformApi<{role_templates:{applied_templates:number,mode:string}}>('/tenants',{method:'POST',body:JSON.stringify({...form,role_template_ids})});modal.value=false;notice.value=`租户 ${form.code} 注册成功，已创建初始管理员；角色初始化方式：${result.role_templates.mode}，共 ${result.role_templates.applied_templates} 个模板`;form.code='';form.name='';form.short_code='';form.admin_login_name='';form.admin_password='123456123456';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function toggle(item:any){const action=item.status==='active'?'disable':'enable';const reason=window.prompt(`请输入${action==='disable'?'停用':'启用'}原因`);if(!reason)return;error.value='';try{await platformApi(`/tenants/${item.id}/${action}`,{method:'POST',body:JSON.stringify({version:item.version,reason})});notice.value=`租户 ${item.code} 已${action==='disable'?'停用':'启用'}`;await load()}catch(e){error.value=(e as Error).message}}
async function saveSetting(){const current=settings.value.find(s=>s.setting_key===setting.setting_key);let value:any=setting.value;try{value=JSON.parse(setting.value)}catch{}saving.value=true;error.value='';try{await platformApi(`/settings/${setting.setting_key}`,{method:'PUT',body:JSON.stringify({value,version:current?.version||0,reason:setting.reason})});notice.value='平台参数已保存为新版本';setting.reason='';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
function editSetting(item:any){setting.setting_key=item.setting_key;setting.value=JSON.stringify(item.setting_value);setting.reason=''}
async function openAdmins(item:any){adminTenant.value=item;temporaryPassword.value='';adminModal.value=true;error.value='';try{adminUsers.value=(await platformApi<{items:any[]}>(`/tenants/${item.id}/admins`)).items}catch(e){error.value=(e as Error).message}}
async function resetPassword(item:any){const reason=window.prompt(`重置 ${item.login_name} 的密码将使其旧密码和全部会话失效，请输入原因`);if(!reason)return;saving.value=true;error.value='';try{const result=await platformApi<{temporary_password:string}>(`/tenants/${adminTenant.value.id}/admins/${item.id}/reset-password`,{method:'POST',body:JSON.stringify({reason})});temporaryPassword.value=result.temporary_password;notice.value='临时密码已生成，请立即复制并安全传达';/* 重新拉取本租户管理员，使“待改密=是”即时反映 */adminUsers.value=(await platformApi<{items:any[]}>(`/tenants/${adminTenant.value.id}/admins`)).items;await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function copyPassword(){if(!temporaryPassword.value)return;await navigator.clipboard.writeText(temporaryPassword.value);notice.value='临时密码已复制'}
function closeAdmins(){adminModal.value=false;temporaryPassword.value=''}
const editTenant=ref<any>(null);const tenantForm=reactive({name:'',short_code:'',timezone:'',reason:''})
/* 制衣厂/待审批制衣厂详情：只读弹窗，展示注册辅助信息（电话、微信、QQ、支付宝等） */
const detailItem=ref<any>(null)
const scaleText:Record<string,string>={micro:'微型',small:'小型',medium:'中型',large:'大型'}
async function openDetail(item:any){detailItem.value=item;error.value='';try{const fetched=await platformApi<any>(`/tenants/${item.id}`);detailItem.value={...item,...fetched}}catch{/* 拉取失败时保留列表行数据 */}}
function openTenant(item:any){editTenant.value=item;Object.assign(tenantForm,{name:item.name,short_code:item.short_code,timezone:item.timezone,reason:''});error.value=''}
async function saveTenant(){if(!editTenant.value)return;saving.value=true;error.value='';try{await platformApi(`/tenants/${editTenant.value.id}`,{method:'PATCH',body:JSON.stringify({...tenantForm,version:editTenant.value.version})});editTenant.value=null;notice.value=`租户 ${tenantForm.short_code} 信息已保存`;await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
function logout(){localStorage.removeItem('clothp_platform_access_token');window.location.href='/platform/login'}
const editionOptions=[{value:'basic',label:'基础版'},{value:'standard',label:'标准版'},{value:'pro',label:'专业版'}]
function openApprove(item:any){approveItem.value=item;/* 体验厂：注册手机号即管理员账户；正式厂默认 {标识}admin */const adminLogin=item.is_trial?(item.contact_phone||''):(item.short_code||'')+'admin';Object.assign(approveForm,{edition:'basic',user_limit:20,short_code:item.short_code||'',admin_login_name:adminLogin,admin_name:item.contact_name||'系统管理员',admin_password:'123456123456',reason:item.is_trial?'体验注册审核通过':''});error.value='';approveModal.value=true}
async function approveReg(){if(!approveItem.value)return;saving.value=true;error.value='';const isTrial=!!approveItem.value.is_trial;try{const r=await platformApi<{admin_login_name:string}>(`/tenant-registrations/${approveItem.value.id}/approve`,{method:'POST',body:JSON.stringify({...approveForm,short_code:approveForm.short_code.trim().toUpperCase()})});approveModal.value=false;notice.value=isTrial?`体验制衣厂「${approveItem.value.name}」已通过审核：注册手机号 ${r.admin_login_name} 即该厂管理员账户，30 天体验期已开始；初始密码供本厂其他员工首次短信/微信登录使用`:`已启用 ${approveItem.value.name}；管理员账号 ${r.admin_login_name}，请将初始密码安全传达（首次登录须修改）`;await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function rejectReg(item:any){const reason=window.prompt(`驳回「${item.name}」的注册申请，请填写原因`);if(!reason)return;saving.value=true;error.value='';try{await platformApi(`/tenant-registrations/${item.id}/reject`,{method:'POST',body:JSON.stringify({reason})});notice.value=`已驳回 ${item.name} 的注册申请`;await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
/* ===== 体验页内容（欢迎词/痛点介绍/解决方案）：存 platform_setting，体验页动态展示 ===== */
const trialContent=reactive({welcome_title:'',welcome_text:'',intro_title:'',pain_points:'',solution_title:'',solution_text:'',reason:''})
function switchToTrial(){tab.value='trial_content';loadTrialContent()}
function loadTrialContent(){const item=settings.value.find(s=>s.setting_key==='trial_page_content');const v=(item?.setting_value||{}) as any;Object.assign(trialContent,{welcome_title:v.welcome_title||'',welcome_text:v.welcome_text||'',intro_title:v.intro_title||'',solution_title:v.solution_title||'',solution_text:v.solution_text||'',reason:''});trialContent.pain_points=(v.pain_points||[]).map((p:any)=>`${p.title}|${p.desc}`).join('\n')}
async function saveTrialContent(){const pain=trialContent.pain_points.split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const idx=l.indexOf('|');const title=idx>=0?l.slice(0,idx).trim():l;const desc=idx>=0?l.slice(idx+1).trim():'';return{title,desc}}).filter(p=>p.title);const current=settings.value.find(s=>s.setting_key==='trial_page_content');saving.value=true;error.value='';try{await platformApi('/settings/trial_page_content',{method:'PUT',body:JSON.stringify({value:{welcome_title:trialContent.welcome_title,welcome_text:trialContent.welcome_text,intro_title:trialContent.intro_title,pain_points:pain,solution_title:trialContent.solution_title,solution_text:trialContent.solution_text},version:current?.version||0,reason:trialContent.reason})});notice.value='体验页内容已保存，体验页刷新即生效（后台改什么，体验页就显示什么）';await load()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function loadAssistants(){error.value='';try{const r=await platformApi<{items:any[];catalog:any[]}>('/assistants');assistants.value=r.items;assistantCatalog.value=r.catalog}catch(e){error.value=(e as Error).message}}
function openAssistant(){Object.assign(assistantForm,{login_name:'',name:'',password:''});Object.keys(assistantForm.permissions).forEach(k=>delete assistantForm.permissions[k]);error.value='';assistantModal.value=true}
async function createAssistant(){const codes=Object.keys(assistantForm.permissions).filter(k=>assistantForm.permissions[k]);if(!assistantForm.login_name||assistantForm.password.length<12){error.value='请填写登录名，密码至少 12 位';return}saving.value=true;error.value='';try{const r=await platformApi<{login_name:string}>('/assistants',{method:'POST',body:JSON.stringify({login_name:assistantForm.login_name,name:assistantForm.name,password:assistantForm.password,permission_codes:codes})});assistantModal.value=false;notice.value=`辅助人员 ${r.login_name} 已创建，初始密码请妥善传达（仅创建时可见输入内容）`;await loadAssistants()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function toggleAssistant(item:any){const action=item.status==='active'?'disabled':'active';const reason=window.prompt(`请输入${action==='active'?'启用':'停用'} ${item.login_name} 的原因`);if(!reason)return;saving.value=true;error.value='';try{await platformApi(`/assistants/${item.id}`,{method:'PATCH',body:JSON.stringify({status:action,name:item.name,reason})});notice.value=`辅助人员 ${item.login_name} 已${action==='active'?'启用':'停用'}`;await loadAssistants()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
function openPermEdit(item:any){permEditItem.value=item;Object.keys(permEdit.codes).forEach(k=>delete permEdit.codes[k]);(item.permission_codes||[]).forEach((c:string)=>permEdit.codes[c]=true);error.value=''}
async function savePermEdit(){if(!permEditItem.value)return;const codes=Object.keys(permEdit.codes).filter(k=>permEdit.codes[k]);saving.value=true;error.value='';try{await platformApi(`/assistants/${permEditItem.value.id}/permissions`,{method:'PUT',body:JSON.stringify({permission_codes:codes})});permEditItem.value=null;notice.value='辅助人员权限已更新';await loadAssistants()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function resetAssistantPassword(item:any){const reason=window.prompt(`重置 ${item.login_name} 的密码将使其旧密码和全部会话失效，请输入原因`);if(!reason)return;saving.value=true;error.value='';try{const result=await platformApi<{temporary_password:string}>(`/assistants/${item.id}/reset-password`,{method:'POST',body:JSON.stringify({reason})});adminTenant.value={code:'辅助人员 · '+item.login_name};adminUsers.value=[];temporaryPassword.value=result.temporary_password;notice.value='临时密码已生成，请立即复制并安全传达';await loadAssistants()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
/* ===== 体验延期审批：体验厂管理员申请 → 平台管理员审批并确定新截止时间 ===== */
const extensions=ref<any[]>([]);const extStatus=ref('pending');const extendItem=ref<any>(null);const extendForm=reactive({new_trial_ends_at:'',reason:''})
const extFormat=(micros:any)=>micros?new Date(Number(micros)/1000).toLocaleString('zh-CN'):'—'
async function loadExtensions(){error.value='';try{const r=await platformApi<{items:any[]}>(`/trial-extensions?status=${extStatus.value}`);extensions.value=r.items}catch(e){error.value=(e as Error).message}}
function openExtendApprove(item:any){extendItem.value=item;const base=Number(item.current_trial_ends_at)||Date.now()*1000;const d=new Date(base/1000+15*86400000);extendForm.new_trial_ends_at=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);extendForm.reason='';error.value=''}
async function approveExtend(){if(!extendItem.value)return;const ms=new Date(extendForm.new_trial_ends_at).getTime()*1000;if(!ms){error.value='请选择新的体验截止时间';return}if(extendItem.value.current_trial_ends_at&&ms<=Number(extendItem.value.current_trial_ends_at)){error.value='新的体验截止时间必须晚于当前截止时间（'+extFormat(extendItem.value.current_trial_ends_at)+'）';return}saving.value=true;error.value='';try{const r=await platformApi<{message:string}>(`/trial-extensions/${extendItem.value.id}/approve`,{method:'POST',body:JSON.stringify({new_trial_ends_at:ms,reason:extendForm.reason})});extendItem.value=null;notice.value=r.message;await loadExtensions()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function rejectExtend(item:any){const reason=window.prompt(`驳回「${item.tenant_name}」的延期申请，请填写原因（可空）`);if(reason===null)return;saving.value=true;error.value='';try{await platformApi(`/trial-extensions/${item.id}/reject`,{method:'POST',body:JSON.stringify({reason})});notice.value='已驳回该延期申请';await loadExtensions()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
onMounted(async()=>{load();try{const me=await platformApi<{role:string}>('/auth/me');role.value=me.role||'assistant'}catch{/* 角色未知时按辅助人员处理 */}})
</script>
<template><div style="max-width:1500px;margin:auto;padding:28px"><div class="page-header"><div><h1>平台控制面</h1><p>独立平台身份 · 租户生命周期 · 平台参数与审计</p></div><div class="header-actions"><RouterLink to="/platform/modules" class="button secondary">功能模块</RouterLink><RouterLink to="/platform/role-templates" class="button secondary">角色模板</RouterLink><RouterLink to="/login" class="button secondary">租户登录</RouterLink><button class="button secondary" @click="logout">退出平台</button></div></div><div class="notice">平台管理员不属于任何租户；统计只返回聚合计数，不提供租户业务敏感明细。</div><div v-if="error" class="notice error">{{error}}</div><div v-if="notice" class="notice success">{{notice}}</div><section class="metrics" style="grid-template-columns:repeat(6,minmax(0,1fr))"><article v-for="c in cards" class="metric"><div class="metric-label">{{c[1]}}</div><div class="metric-value">{{metrics[c[0]]??0}}</div></article></section><section class="panel"><div class="tabs"><button :class="{active:tab==='tenants'}" @click="tab='tenants'">租户运营</button><button :class="{active:tab==='registrations'}" @click="tab='registrations'">注册审批</button><button :class="{active:tab==='trial_extend'}" @click="tab='trial_extend';loadExtensions()">体验延期</button><button v-if="role==='super'" :class="{active:tab==='assistants'}" @click="tab='assistants';loadAssistants()">辅助人员</button><button :class="{active:tab==='trial_content'}" @click="switchToTrial">体验页内容</button><button :class="{active:tab==='settings'}" @click="tab='settings'">平台参数</button><button :class="{active:tab==='audit'}" @click="tab='audit'">平台审计</button></div><PageState :loading="loading"/>
<div v-if="!loading&&tab==='registrations'"><div class="toolbar"><FilterSelect v-model="regStatus" :options="[{value:'pending',label:'待审核'},{value:'approved',label:'已启用'},{value:'rejected',label:'已驳回'}]" @update:model-value="load"/><span class="spacer"></span><button class="button secondary" @click="load">刷新</button></div><div class="table-wrap"><table><thead><tr><th>厂编码</th><th>厂名称</th><th>用户类型</th><th>标识</th><th>联系人</th><th>联系电话</th><th>所在国/地区</th><th>厂规模</th><th>申请时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in registrations"><td><strong>{{item.code}}</strong></td><td>{{item.name}}</td><td><span class="status" :class="item.is_trial?'pending':'active'">{{item.is_trial?'体验用户':'付费用户'}}</span><span v-if="item.expedited" class="status pending" style="margin-left:6px" title="该厂已申请加急，优先审批">🔥 加急</span></td><td>{{item.short_code}}</td><td>{{item.contact_name||'—'}}</td><td>{{item.contact_phone||'—'}}</td><td>{{item.region||'—'}}</td><td>{{item.scale||'—'}}</td><td>{{formatTime(item.created_at)}}</td><td><button class="button link" @click="openDetail(item)">详细</button><template v-if="item.registration_status==='pending'"><button class="button link" @click="openApprove(item)">审批启用</button><button class="button link text-danger" @click="rejectReg(item)">驳回</button></template><span v-else class="status" :class="item.registration_status==='approved'?'active':'pending'">{{item.registration_status==='approved'?'已启用':'已驳回'}}</span></td></tr></tbody></table><PageState :empty="!registrations.length"/></div><div class="notice" style="margin-top:12px">审批启用时确认订阅版本与订阅规模（启用用户数上限），并为本厂分配管理员账户与初始密码；系统同时创建组织、角色权限与本厂数据加密密钥。</div></div>
<div v-if="!loading&&tab==='trial_extend'"><div class="toolbar"><FilterSelect v-model="extStatus" :options="[{value:'pending',label:'待审批'},{value:'approved',label:'已批准'},{value:'rejected',label:'已驳回'},{value:'all',label:'全部'}]" @update:model-value="loadExtensions"/><span class="spacer"></span><button class="button secondary" @click="loadExtensions">刷新</button></div><div class="table-wrap"><table><thead><tr><th>厂编码</th><th>厂名称</th><th>申请人手机号</th><th>延期原因</th><th>当前体验截止</th><th>申请时间</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="item in extensions"><td><strong>{{item.tenant_code}}</strong></td><td>{{item.tenant_name}}</td><td>{{item.requested_phone}}</td><td>{{item.reason||'—'}}</td><td>{{extFormat(item.current_trial_ends_at)}}</td><td>{{extFormat(item.created_at)}}</td><td><span class="status" :class="item.status==='approved'?'active':item.status==='rejected'?'disabled':'pending'">{{item.status==='approved'?'已批准':item.status==='rejected'?'已驳回':'待审批'}}</span><span v-if="item.status==='approved'" style="margin-left:6px;font-size:12px">新截止：{{extFormat(item.new_trial_ends_at)}}</span><span v-else-if="item.status==='rejected'&&item.review_reason" style="margin-left:6px;font-size:12px">原因：{{item.review_reason}}</span></td><td><template v-if="item.status==='pending'"><button class="button link" @click="openExtendApprove(item)">批准延期</button><button class="button link text-danger" @click="rejectExtend(item)">驳回</button></template><span v-else class="text-muted">已处理</span></td></tr></tbody></table><PageState :empty="!extensions.length"/></div><div class="notice" style="margin-top:12px">体验厂管理员在体验主页「申请延长体验」提交申请；批准时由平台管理员确定新的体验截止时间（须晚于当前截止时间），通过后该厂 tenant_subscription 的体验期即更新。</div></div>
<div v-if="!loading&&tab==='tenants'"><div class="toolbar"><input v-model.trim="tenantsQuery" class="search-input" placeholder="搜索租户编码/名称/标识/联系人/联系电话（回车查询）" @keyup.enter="load"><button class="button secondary" @click="load">查询</button><span class="spacer"></span><button class="button secondary" @click="load">刷新</button><button class="button" @click="openRegister">+ 注册租户</button></div><div class="table-wrap"><table><thead><tr><th>编码</th><th>标识</th><th>名称</th><th>用户类型</th><th>联系人</th><th>联系电话</th><th>时区</th><th>状态</th><th>用户数</th><th>工单数</th><th>报工数</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in tenants"><td><strong>{{item.code}}</strong></td><td>{{item.short_code}}</td><td>{{item.name}}</td><td><span class="status" :class="item.customer_type==='trial'?'pending':'active'">{{item.customer_type==='trial'?'体验用户':'付费用户'}}</span></td><td>{{item.contact_name||'—'}}</td><td>{{item.contact_phone||'—'}}</td><td>{{item.timezone}}</td><td><span class="status" :class="item.status">{{statusText[item.status]}}</span><span v-if="item.registration_status==='pending'" class="status pending" style="margin-left:6px">待审核</span><span v-else-if="item.registration_status==='rejected'" class="status disabled" style="margin-left:6px">注册驳回</span></td><td>{{item.user_count}}</td><td>{{item.work_order_count}}</td><td>{{item.report_count}}</td><td>{{formatTime(item.created_at)}}</td><td><button class="button link" @click="openDetail(item)">详细</button><button class="button link" @click="openTenant(item)">编辑</button><button class="button link" @click="openAdmins(item)">管理员/重置密码</button><button class="button link" :class="{'text-danger':item.status==='active'}" @click="toggle(item)">{{item.status==='active'?'停用':'启用'}}</button></td></tr></tbody></table><PageState :empty="!tenants.length"/></div></div>
<div v-if="!loading&&tab==='trial_content'" class="panel-body"><div class="notice">体验页三段内容（动态展示，改什么体验页就显示什么）：① 欢迎词 ② 功能介绍（点出客户痛点，每行一条，格式：<code>标题|描述</code>）③ 解决方案；体验页在解决方案处提供 继续体验 / 暂停下次继续 / 退出体验 三种选择。</div><div class="form-grid"><div class="field full"><label class="required">欢迎标题</label><input v-model.trim="trialContent.welcome_title" placeholder="如：欢迎使用一智算制衣 MES"></div><div class="field full"><label class="required">欢迎词</label><textarea v-model="trialContent.welcome_text" rows="3"></textarea></div><div class="field full"><label class="required">功能介绍标题（痛点引入）</label><input v-model.trim="trialContent.intro_title" placeholder="如：这些场景，您是不是也遇到过？"></div><div class="field full"><label class="required">痛点列表（每行一条：标题|描述）</label><textarea v-model="trialContent.pain_points" rows="5" placeholder="订单进度靠问|货期临近才发现某道工序堆货…"></textarea></div><div class="field full"><label class="required">解决方案标题</label><input v-model.trim="trialContent.solution_title"></div><div class="field full"><label class="required">解决方案说明</label><textarea v-model="trialContent.solution_text" rows="3"></textarea></div><div class="field full"><label class="required">变更原因</label><input v-model.trim="trialContent.reason" placeholder="记录本次修改原因（审计）"></div></div><div class="form-actions"><button class="button" :disabled="saving||!trialContent.reason" @click="saveTrialContent">保存并发布</button></div></div>
<div v-if="!loading&&tab==='settings'" class="panel-body"><div class="form-grid"><div class="field"><label>参数键</label><input v-model.trim="setting.setting_key" placeholder="例如 registration.enabled"></div><div class="field"><label>参数值（JSON 或文本）</label><input v-model="setting.value" placeholder='例如 true 或 "production"'></div><div class="field full"><label class="required">变更原因</label><input v-model="setting.reason"></div></div><div class="form-actions"><button class="button" :disabled="saving||!setting.setting_key||!setting.reason" @click="saveSetting">保存为新版本</button></div><div class="table-wrap"><table><thead><tr><th>参数键</th><th>当前值</th><th>版本</th><th>原因</th><th>操作</th></tr></thead><tbody><tr v-for="item in settings"><td>{{item.setting_key}}</td><td>{{JSON.stringify(item.setting_value)}}</td><td>v{{item.version}}</td><td>{{item.change_reason}}</td><td><button class="button link" @click="editSetting(item)">编辑</button></td></tr></tbody></table><PageState :empty="!settings.length"/></div></div>
<div v-if="!loading&&tab==='assistants'"><div class="notice">平台辅助人员由平台管理员统一创建与分配权限；辅助人员<strong>不能</strong>添加或管理平台管理员与辅助人员，其余功能按所分配权限访问。</div><div class="toolbar"><span class="spacer"></span><button class="button secondary" @click="loadAssistants">刷新</button><button class="button" @click="openAssistant">+ 新建辅助人员</button></div><div class="table-wrap"><table><thead><tr><th>登录名</th><th>姓名</th><th>状态</th><th>已分配权限</th><th>最近登录</th><th>操作</th></tr></thead><tbody><tr v-for="item in assistants"><td><strong>{{item.login_name}}</strong></td><td>{{item.name||'—'}}</td><td><span class="status" :class="item.status">{{item.status==='active'?'启用':'停用'}}</span></td><td>{{(item.permission_codes||[]).length||0}} 项</td><td>{{item.last_login_at?formatTime(item.last_login_at):'从未'}}</td><td><button class="button link" @click="openPermEdit(item)">分配权限</button><button class="button link" @click="resetAssistantPassword(item)">重置密码</button><button class="button link" :class="{'text-danger':item.status==='active'}" @click="toggleAssistant(item)">{{item.status==='active'?'停用':'启用'}}</button></td></tr></tbody></table><PageState :empty="!assistants.length"/></div></div>
<div v-if="!loading&&tab==='audit'" class="table-wrap"><table><thead><tr><th>时间</th><th>动作</th><th>对象类型</th><th>对象ID</th><th>原因</th><th>请求ID</th></tr></thead><tbody><tr v-for="item in audits"><td>{{formatTime(item.created_at)}}</td><td>{{item.action}}</td><td>{{item.owner_type}}</td><td>{{item.owner_id}}</td><td>{{item.reason||'—'}}</td><td class="text-muted">{{item.request_id}}</td></tr></tbody></table><PageState :empty="!audits.length"/></div></section></div>
<ModalDialog v-if="modal" wide title="注册新租户" @close="modal=false"><div class="form-grid"><div class="field"><label class="required">租户编码</label><input v-model.trim="form.code" placeholder="2-32位字母、数字、_或-"></div><div class="field"><label class="required">租户名称</label><input v-model.trim="form.name" @input="onTenantNameInput"></div><div class="field"><label>租户标识</label><input v-model.trim="form.short_code" maxlength="5" placeholder="留空按名称首字母生成" @input="onShortCodeInput"><small class="text-muted">用于生成工号前缀与管理员账号</small></div><div class="field"><label>默认时区</label><input v-model.trim="form.timezone"></div><div class="field"><label>初始管理员姓名</label><input v-model.trim="form.admin_name"></div><div class="field"><label>初始管理员账号</label><input :value="form.admin_login_name" disabled><small class="text-muted">默认 {租户标识}admin，重名时自动调整标识</small></div><div class="field"><label class="required">初始管理员密码</label><input v-model="form.admin_password" type="password" autocomplete="new-password" placeholder="至少12位"><small class="text-muted">默认 123456123456，首次登录必须修改</small></div><div class="field full"><label>平台角色初始化</label><FilterSelect v-model="form.role_template_mode" :options="[{value:'all',label:'全部复制'},{value:'none',label:'不复制'},{value:'custom',label:'部分复制'}]"/></div><div v-if="form.role_template_mode==='custom'" class="field full"><label>选择角色模板</label><label v-for="item in roleTemplates" :key="item.id" style="display:block;margin:6px"><input v-model="selectedRoleTemplates[item.id]" type="checkbox"> {{item.name}} <small class="text-muted">{{item.code}}</small></label></div></div><div class="notice" style="margin-top:16px">将在同一事务中创建组织、固定管理员账号、身份权限和默认配置；角色模板按所选范围复制为租户角色，不获得其他租户的数据权限。</div><template #footer><button class="button secondary" @click="modal=false">取消</button><button class="button" :disabled="saving" @click="register">确认注册</button></template></ModalDialog>
<ModalDialog v-if="detailItem" wide :title="`制衣厂详情 · ${detailItem.name || ''}`" @close="detailItem=null"><div class="table-wrap"><table><tbody><tr><th style="width:140px">厂编码</th><td><strong>{{detailItem.code}}</strong></td></tr><tr><th>厂标识</th><td>{{detailItem.short_code||'—'}}</td></tr><tr><th>厂名称</th><td>{{detailItem.name}}</td></tr><tr><th>用户类型</th><td>{{detailItem.customer_type==='trial'?'体验用户':'付费用户'}}</td></tr><tr><th>运营状态</th><td>{{statusText[detailItem.status]||detailItem.status}}</td></tr><tr><th>注册状态</th><td><span class="status" :class="detailItem.registration_status==='approved'?'active':'pending'">{{detailItem.registration_status==='approved'?'已启用':detailItem.registration_status==='rejected'?'已驳回':'待审核'}}</span></td></tr><tr v-if="detailItem.expedited"><th>加急</th><td>已申请加急审批</td></tr><tr><th>联系人</th><td>{{detailItem.contact_name||'—'}}</td></tr><tr><th>联系电话</th><td>{{detailItem.contact_phone||'—'}}</td></tr><tr><th>微信号</th><td>{{detailItem.contact_wechat||'—'}}</td></tr><tr><th>QQ</th><td>{{detailItem.contact_qq||'—'}}</td></tr><tr><th>支付宝账号</th><td>{{detailItem.contact_alipay||'—'}}</td></tr><tr><th>所在国 / 地区</th><td>{{detailItem.region||'—'}}</td></tr><tr><th>厂规模</th><td>{{scaleText[detailItem.scale]||detailItem.scale||'—'}}</td></tr><tr><th>厂地址</th><td>{{detailItem.address||'—'}}</td></tr><tr><th>备注</th><td>{{detailItem.remark||'—'}}</td></tr><tr><th>管理员登录名</th><td>{{detailItem.admin_login_name||'—'}}</td></tr><tr><th>注册时间</th><td>{{formatTime(detailItem.registered_at)}}</td></tr><tr><th>审批时间</th><td>{{formatTime(detailItem.approved_at)}}</td></tr><tr><th>创建时间</th><td>{{formatTime(detailItem.created_at)}}</td></tr><tr><th>用户数 / 工单数 / 报工数</th><td>{{detailItem.user_count??'—'}} / {{detailItem.work_order_count??'—'}} / {{detailItem.report_count??'—'}}</td></tr></tbody></table></div><div class="form-actions"><button class="button secondary" @click="detailItem=null">关闭</button></div></ModalDialog><ModalDialog v-if="editTenant" :title="`编辑租户 · ${editTenant.code}`" @close="editTenant=null"><div v-if="error" class="notice error">{{error}}</div><div class="form-grid"><div class="field"><label class="required">租户名称</label><input v-model.trim="tenantForm.name"></div><div class="field"><label class="required">租户标识</label><input v-model.trim="tenantForm.short_code" maxlength="5" placeholder="5 位字母或数字"><small class="text-muted">用于生成员工工号前缀，例如 ABC01-000001</small></div><div class="field"><label>时区</label><input v-model.trim="tenantForm.timezone"></div><div class="field full"><label>变更原因</label><input v-model.trim="tenantForm.reason"></div></div><div class="notice" style="margin-top:14px">修改标识后，新生成的工号使用新前缀；已存在的工号不会自动改写。</div><template #footer><button class="button secondary" @click="editTenant=null">取消</button><button class="button" :disabled="saving || !tenantForm.name || tenantForm.short_code.length !== 5" @click="saveTenant">保存</button></template></ModalDialog>
<ModalDialog v-if="adminModal" wide :title="`租户管理员 · ${adminTenant?.code || ''}`" @close="closeAdmins"><div v-if="temporaryPassword" class="notice success"><strong>临时密码仅显示一次，请立即复制：</strong><div style="display:flex;gap:10px;margin-top:12px"><input :value="temporaryPassword" readonly style="flex:1"><button class="button" @click="copyPassword">复制密码</button></div><small>临时密码为12位，包含大写字母、小写字母、数字和符号。旧密码和该管理员的全部会话已失效，下次登录必须设置新密码。</small></div><div class="table-wrap"><table><thead><tr><th>账号</th><th>姓名</th><th>状态</th><th>待改密</th><th>操作</th></tr></thead><tbody><tr v-for="item in adminUsers"><td>{{item.login_name}}</td><td>{{item.name}}</td><td>{{statusText[item.status]||item.status}}</td><td>{{item.password_change_required?'是':'否'}}</td><td><button class="button link text-danger" :disabled="saving" @click="resetPassword(item)">重置密码</button></td></tr></tbody></table><PageState :empty="!adminUsers.length"/></div><template #footer><button class="button secondary" @click="closeAdmins">关闭</button></template></ModalDialog>
<ModalDialog v-if="approveModal" wide :title="`${approveItem?.is_trial ? '体验厂审批' : '审批启用'} · ${approveItem?.name || ''}`" @close="approveModal=false"><div v-if="error" class="notice error">{{error}}</div><div class="form-grid"><div class="field"><label class="required">订阅版本</label><FilterSelect v-model="approveForm.edition" :options="editionOptions"/></div><div class="field"><label class="required">订阅规模（启用用户数上限）</label><input v-model.number="approveForm.user_limit" type="number" min="1" max="10000"></div><div class="field"><label>租户标识</label><input v-model.trim="approveForm.short_code" maxlength="5" placeholder="5 位字母或数字"><small class="text-muted">用于工号前缀与管理员账号</small></div><div class="field"><label>管理员账号</label><input v-model.trim="approveForm.admin_login_name" :placeholder="approveItem?.is_trial ? '默认使用注册手机号' : '默认 {租户标识}admin'"></div><div class="field"><label>管理员姓名</label><input v-model.trim="approveForm.admin_name"></div><div class="field"><label class="required">初始密码</label><input v-model="approveForm.admin_password" type="password" autocomplete="new-password" placeholder="至少12位，首次登录须修改"></div><div class="field full"><label>备注/原因</label><input v-model.trim="approveForm.reason" placeholder="如：已签订体验协议"></div></div><div class="notice" style="margin-top:14px">{{approveItem?.is_trial ? '体验厂通过审核后开始 30 天体验期：注册手机号即该厂管理员账户，可直接使用手机号/微信登录；初始密码供本厂其他员工首次短信/微信登录使用。' : '启用后制衣厂管理员即可登录进入业务主页；订阅规模将限制该厂可启用的用户数量。业务参数由制衣厂管理员自行配置（后续版本开放）。'}}</div><template #footer><button class="button secondary" @click="approveModal=false">取消</button><button class="button" :disabled="saving||!approveForm.user_limit||approveForm.admin_password.length<12" @click="approveReg">{{saving?'处理中…':'确认启用'}}</button></template></ModalDialog>
<ModalDialog v-if="assistantModal" title="新建平台辅助人员" @close="assistantModal=false"><div v-if="error" class="notice error">{{error}}</div><div class="form-grid"><div class="field"><label class="required">登录名</label><input v-model.trim="assistantForm.login_name" placeholder="3-32 位小写字母、数字或 _"></div><div class="field"><label>姓名</label><input v-model.trim="assistantForm.name"></div><div class="field full"><label class="required">初始密码</label><input v-model="assistantForm.password" type="password" autocomplete="new-password" placeholder="至少 12 位"><small class="text-muted">仅创建时输入一次，请立即安全传达</small></div><div class="field full"><label>分配权限（留空表示暂不分配）</label><div style="max-height:220px;overflow:auto;border:1px solid #e2e8f0;border-radius:8px;padding:8px"><label v-for="p in assistantCatalog" :key="p.code" style="display:block;margin:4px 0;font-size:13px"><input v-model="assistantForm.permissions[p.code]" type="checkbox"> {{p.name}} <small class="text-muted">{{p.code}}</small></label></div><small class="text-muted">辅助人员永远无法创建/管理平台管理员与辅助人员</small></div></div><template #footer><button class="button secondary" @click="assistantModal=false">取消</button><button class="button" :disabled="saving" @click="createAssistant">确认创建</button></template></ModalDialog>
<ModalDialog v-if="permEditItem" :title="`分配权限 · ${permEditItem.login_name}`" @close="permEditItem=null"><div v-if="error" class="notice error">{{error}}</div><div style="max-height:320px;overflow:auto;border:1px solid #e2e8f0;border-radius:8px;padding:8px"><label v-for="p in assistantCatalog" :key="p.code" style="display:block;margin:4px 0;font-size:13px"><input v-model="permEdit.codes[p.code]" type="checkbox"> {{p.name}} <small class="text-muted">{{p.code}}</small></label></div><template #footer><button class="button secondary" @click="permEditItem=null">取消</button><button class="button" :disabled="saving" @click="savePermEdit">保存权限</button></template></ModalDialog>
<ModalDialog v-if="extendItem" :title="`批准延期 · ${extendItem.tenant_name || ''}`" @close="extendItem=null"><div v-if="error" class="notice error">{{error}}</div><div class="form-grid"><div class="field"><label>申请人手机号</label><input :value="extendItem.requested_phone" disabled></div><div class="field"><label>当前体验截止</label><input :value="extFormat(extendItem.current_trial_ends_at)" disabled></div><div class="field"><label>延期原因</label><input :value="extendItem.reason||'—'" disabled></div><div class="field full"><label class="required">新的体验截止时间</label><input v-model="extendForm.new_trial_ends_at" type="datetime-local"><small class="text-muted">默认为当前截止时间 + 15 天；必须晚于当前截止时间，批准后该厂体验期即更新</small></div><div class="field full"><label>备注/原因</label><input v-model.trim="extendForm.reason" placeholder="如：体验转化谈判中"></div></div><template #footer><button class="button secondary" @click="extendItem=null">取消</button><button class="button" :disabled="saving" @click="approveExtend">{{saving?'处理中…':'确认批准延期'}}</button></template></ModalDialog></template>
